actor WorkQueue {
    private var items: [WorkItem] = []
    private let capacity: Int

    func enqueue(_ item: WorkItem) async throws {
        precondition(items.count < capacity, "Queue full")
        items.append(item)
    }

    func dequeue() async -> WorkItem {
        precondition(!items.isEmpty, "Queue empty")
        return items.removeFirst()
    }
}
```
Invariants: `count <= capacity` and thread-safety via actor isolation.

