@MainActor func testEnqueueDequeue() async throws {
    let q = WorkQueue(capacity: 2)
    try await q.enqueue(.init())
    let item = await q.dequeue()
    XCTAssertNotNil(item)
}

@MainActor func testCancellation() async throws {
    let q = WorkQueue(capacity: 1)
    try await q.enqueue(.init())
    let task = Task { try await q.dequeue() }
    task.cancel()
    try await task.value
}
